import React from 'react';
import { useUser } from '../hooks/useUser';
import styles from './ProfileCard.module.css';

interface ProfileCardProps {
  userId: string;
  showEmail?: boolean;
}

export function ProfileCard({ userId, showEmail = false }: ProfileCardProps) {
  const { user, isLoading, error } = useUser(userId);

  if (isLoading) return <div className={styles.skeleton}>Loading...</div>;
  if (error) return <div className={styles.error}>Could not load profile</div>;
  if (!user) return null;

  return (
    <div className={styles.card}>
      <img src={user.avatarUrl} alt={`${user.displayName} avatar`} className={styles.avatar} />
      <h3 className={styles.name}>{user.displayName}</h3>
      <p className={styles.title}>{user.jobTitle}</p>
      {showEmail && <p className={styles.email}>{user.email}</p>}
      <span className={styles.badge}>{user.teamName}</span>
    </div>
  );
}

import { useState, useEffect } from 'react';
import { apiClient } from '../lib/apiClient';

interface User {
  id: string;
  displayName: string;
  email: string;
  avatarUrl: string;
  jobTitle: string;
  teamName: string;
}

export function useUser(userId: string) {
  const [user, setUser] = useState<User | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<Error | null>(null);

  useEffect(() => {
    let cancelled = false;
    setIsLoading(true);

    apiClient.get<User>(`/users/${userId}`)
      .then((data) => {
        if (!cancelled) setUser(data);
      })
      .catch((err) => {
        if (!cancelled) setError(err);
      })
      .finally(() => {
        if (!cancelled) setIsLoading(false);
      });

    return () => { cancelled = true; };
  }, [userId]);

  return { user, isLoading, error };
}

