package main

import (
	"flag"
	"fmt"
	"log"
	"os"

	"github.com/acme/filesync/internal/sync"
)

func main() {
	sourceDir := flag.String("source", "", "directory to sync from")
	destDir := flag.String("dest", "", "directory to sync to")
	dryRun := flag.Bool("dry-run", false, "print actions without executing them")
	verbose := flag.Bool("v", false, "enable verbose logging")
	flag.Parse()

	if *sourceDir == "" || *destDir == "" {
		fmt.Fprintln(os.Stderr, "both -source and -dest are required")
		flag.Usage()
		os.Exit(1)
	}

	opts := sync.Options{
		DryRun:  *dryRun,
		Verbose: *verbose,
	}

	result, err := sync.Run(*sourceDir, *destDir, opts)
	if err != nil {
		log.Fatalf("sync failed: %v", err)
	}

	fmt.Printf("synced %d files, skipped %d, %d errors\n",
		result.Copied, result.Skipped, len(result.Errors))
}

use clap::{Parser, Subcommand};

#[derive(Parser)]
#[command(name = "taskrunner", version, about = "Run and monitor local tasks")]
pub struct Cli {
    #[command(subcommand)]
    pub command: Commands,

    /// Increase output verbosity
    #[arg(short, long, global = true)]
    pub verbose: bool,
}

#[derive(Subcommand)]
pub enum Commands {
    /// Start a task by name
    Run {
        name: String,
        #[arg(long, default_value_t = 3)]
        retries: u32,
    },
    /// List all configured tasks
    List,
    /// Show status of a running task
    Status { name: String },
}

pub fn parse_args() -> Cli {
    Cli::parse()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn parses_run_command() {
        let cli = Cli::parse_from(["taskrunner", "run", "build", "--retries", "5"]);
        match cli.command {
            Commands::Run { name, retries } => {
                assert_eq!(name, "build");
                assert_eq!(retries, 5);
            }
            _ => panic!("expected Run command"),
        }
    }
}

package config

import (
	"fmt"
	"time"
)

type Config struct {
	MaxRetries      int           `yaml:"max_retries"`
	Timeout         time.Duration `yaml:"timeout"`
	WorkerCount     int           `yaml:"worker_count"`
	LogLevel        string        `yaml:"log_level"`
	OutputDirectory string        `yaml:"output_directory"`
}

func Default() Config {
	return Config{
		MaxRetries:      3,
		Timeout:         30 * time.Second,
		WorkerCount:     4,
		LogLevel:        "info",
		OutputDirectory: "./output",
	}
}

func (c Config) Validate() error {
	if c.WorkerCount < 1 {
		return fmt.Errorf("worker_count must be at least 1, got %d", c.WorkerCount)
	}
	if c.MaxRetries < 0 {
		return fmt.Errorf("max_retries cannot be negative")
	}
	return nil
}

variable "bucket_name" {
  description = "Name of the S3 bucket"
  type        = string
}

variable "environment" {
  description = "Deployment environment (dev, staging, prod)"
  type        = string
}

resource "aws_s3_bucket" "reports" {
  bucket = var.bucket_name

  tags = {
    Environment = var.environment
    ManagedBy   = "terraform"
    Team        = "data-platform"
  }
}

resource "aws_s3_bucket_versioning" "reports" {
  bucket = aws_s3_bucket.reports.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_lifecycle_configuration" "reports" {
  bucket = aws_s3_bucket.reports.id

  rule {
    id     = "expire-old-versions"
    status = "Enabled"

    noncurrent_version_expiration {
      noncurrent_days = 90
    }
  }
}

output "bucket_arn" {
  value = aws_s3_bucket.reports.arn
}

